import styled from '@emotion/styled';
import { Search, X } from 'components/icon';
import { theme } from 'theme';

import type { SearchFieldSize } from './SearchField.types';

interface StyledWrapperProps {
  $size: SearchFieldSize;
  $disabled?: boolean;
  $width?: string | number;
}

interface StyledInputContainerProps {
  $size: SearchFieldSize;
}

interface StyledClearButtonProps {
  $isVisible: boolean;
}

const sizeWrapperStyles: Record<
  SearchFieldSize,
  { fontSize: string; lineHeight: string; height: string }
> = {
  medium: {
    fontSize: theme.fonts.fontSizes['2'],
    lineHeight: theme.fonts.lineHeights['3'],
    height: '2.5rem',
  },
  large: {
    fontSize: theme.fonts.fontSizes['4'],
    lineHeight: theme.fonts.lineHeights['6'],
    height: '3rem',
  },
};

/** Hexa Input base line-height ($6) — keeps Ctrl+A selection tight to text, not full field height */
const inputLineHeight = theme.fonts.lineHeights['6'];

export const StyledWrapper = styled('div')<StyledWrapperProps>(
  ({ $size, $disabled, $width }) => ({
    alignItems: 'center',
    background: theme.colors.interfaceSurfacePrimary,
    borderRadius: '9999px',
    boxSizing: 'border-box',
    display: 'flex',
    minWidth: '140px',
    padding: `${theme.spacing['1']} 16px ${theme.spacing['1']} ${theme.spacing['2']}`,
    width: $width ?? '100%',
    ...sizeWrapperStyles[$size],
    ...($disabled && {
      '& svg': {
        color: theme.colors.interfaceLabelDisabled,
      },
    }),
    '&:hover svg.search-icon': {
      color: theme.colors.interfaceLabelPrimary,
    },
    '&:focus-within svg.search-icon': {
      color: theme.colors.interfaceLabelPrimary,
    },
  }),
);

export const StyledInputWrapper = styled('div')({
  alignItems: 'center',
  color: theme.colors.interfaceLabelPrimary,
  display: 'flex',
  flex: 1,
  fontFamily: theme.fonts.paragraph,
});

export const StyledSearchIcon = styled(Search, {
  shouldForwardProp: (prop) => prop !== 'disabled',
})<{ disabled?: boolean }>(({ disabled }) => ({
  color: theme.colors.interfaceLabelSecondary,
  ...(disabled && {
    color: theme.colors.interfaceLabelDisabled,
  }),
}));

export const StyledInputContainer = styled('div')<StyledInputContainerProps>(
  ({ $size }) => ({
    display: 'flex',
    flex: 1,
    margin: `0 ${theme.spacing['2']}`,
    '& div': {
      outline: 'none',
    },
    '& input': {
      backgroundColor: 'transparent',
      fontSize: sizeWrapperStyles[$size].fontSize,
      height: sizeWrapperStyles[$size].height,
      lineHeight: inputLineHeight,
      padding: 0,
      width: '100%',
      border: 'none',
      outline: 'none',
      fontFamily: theme.fonts.paragraph,
      fontWeight: theme.fonts.fontWeights.normal,
      color: theme.colors.interfaceLabelPrimary,
      '&::placeholder': {
        color: theme.colors.interfaceLabelSecondary,
      },
      '&:disabled': {
        color: theme.colors.interfaceLabelDisabled,
        cursor: 'not-allowed',
      },
    },
  }),
);

export const StyledClearButton = styled('button')<StyledClearButtonProps>(
  ({ $isVisible }) => ({
    alignItems: 'center',
    backgroundColor: theme.colors.interfaceSurfacePrimary,
    border: 'none',
    borderRadius: '999px',
    cursor: 'pointer',
    display: 'flex',
    height: '24px',
    justifyContent: 'center',
    opacity: 1,
    padding: '7px',
    width: '24px',
    visibility: $isVisible ? 'visible' : 'hidden',
    '&:disabled': {
      cursor: 'auto',
    },
    '& svg': {
      color: theme.colors.interfaceLabelPrimary,
    },
  }),
);

export const StyledClearIcon = styled(X)({
  color: theme.colors.interfaceLabelPrimary,
});
